  rules.clear();for(String s:config.getStringList("classAnimations","compatibility",new String[0],"class|duration|offset|easing|style|direction")){Map.Entry<String,ScreenRule>e=parseScreenRule(s);if(e!=null)rules.put(e.getKey(),e.getValue());}
