 public static synchronized Policy policy(String n){return policy(n,null);}public static synchronized Policy policy(String n,String mod){Policy p=policies.get(n);if(p!=null)return p;p=validMod(mod)?modPolicies.get(mod):null;return p==null?Policy.DEFAULT:p;}public static synchronized Policy ownPolicy(String n){Policy p=policies.get(n);return p==null?Policy.DEFAULT:p;}public static synchronized Policy modPolicy(String mod){Policy p=modPolicies.get(mod);return p==null?Policy.DEFAULT:p;}public static synchronized AnimationProfile profile(){return profile;}public static synchronized ClosingMode closingMode(){return closingMode;}public static synchronized boolean animationAllowed(Class<?>t){return animationAllowed(t.getName(),null);}public static synchronized boolean animationAllowed(String n){return animationAllowed(n,null);}public static synchronized boolean animationAllowed(String n,String mod){return policy(n,mod)!=Policy.DISABLED;}
 public static synchronized BackgroundMode backgroundMode(String n){BackgroundMode m=backgroundModes.get(n);return m==null?BackgroundMode.AUTO:m;}public static synchronized void setBackgroundMode(String n,BackgroundMode m){if(m==BackgroundMode.AUTO)backgroundModes.remove(n);else backgroundModes.put(n,m);saveBackgroundModes();}
