 public static synchronized void setRule(String n,int d,int o,ScreenEasing e){ScreenRule r=rule(n);setRule(n,d,o,e,r.style,r.direction);}public static synchronized void setRule(String n,int d,int o,ScreenEasing e,AnimationStyle s,AnimationDirection a){rules.put(n,new ScreenRule(clamp(d,0,600),clamp(o,0,48),e,s,a));saveRules();}public static synchronized void setClosingRule(String n,ClosingMode m,int d,int o,ScreenEasing e){ClosingRule r=closingRule(n);setClosingRule(n,m,d,o,e,r.style,r.direction);}public static synchronized void setClosingRule(String n,ClosingMode m,int d,int o,ScreenEasing e,AnimationStyle s,AnimationDirection a){closingRules.put(n,new ClosingRule(m,clamp(d,0,600),clamp(o,0,48),e,s,a));saveClosingRules();}public static synchronized void resetOpening(String n){rules.remove(n);policies.remove(n);saveRules();savePolicies();}public static synchronized void resetClosing(String n){closingRules.remove(n);saveClosingRules();}public static synchronized void resetRule(String n){rules.remove(n);policies.remove(n);closingRules.remove(n);saveRules();savePolicies();saveClosingRules();}
 public static synchronized void setModPolicy(String mod,Policy p){requireMod(mod);if(p==Policy.DEFAULT)modPolicies.remove(mod);else modPolicies.put(mod,p);saveModPolicies();}public static synchronized void setModRule(String mod,int d,int o,ScreenEasing e,AnimationStyle s,AnimationDirection a){requireMod(mod);modRules.put(mod,new ScreenRule(clamp(d,0,600),clamp(o,0,48),e,s,a));saveModRules();}public static synchronized void setModClosingRule(String mod,ClosingMode m,int d,int o,ScreenEasing e,AnimationStyle s,AnimationDirection a){requireMod(mod);modClosingRules.put(mod,new ClosingRule(m,clamp(d,0,600),clamp(o,0,48),e,s,a));saveModClosingRules();}public static synchronized void resetModOpening(String mod){modRules.remove(mod);modPolicies.remove(mod);saveModRules();saveModPolicies();}public static synchronized void resetModClosing(String mod){modClosingRules.remove(mod);saveModClosingRules();}
 public static synchronized int applyOpening(Collection<String> names,ScreenRule rule,Policy policy){int count=0;for(String n:names)if(n!=null&&!n.isEmpty()){if(policy==Policy.DEFAULT)policies.remove(n);else policies.put(n,policy);rules.put(n,copy(rule));count++;}savePolicies();saveRules();return count;}public static synchronized int applyClosing(Collection<String> names,ClosingRule rule){int count=0;for(String n:names)if(n!=null&&!n.isEmpty()){closingRules.put(n,copy(rule));count++;}saveClosingRules();return count;}
 public static synchronized ClosingMode cycleClosingMode(){return cycleClosingMode(1);}public static synchronized ClosingMode cycleClosingMode(int direction){ClosingMode[]v=ClosingMode.values();closingMode=v[wrap(closingMode.ordinal()+(direction<0?-1:1),v.length)];closing=closingMode!=ClosingMode.DISABLED;profile=matchingProfile();saveProfile();return closingMode;}public static synchronized AnimationProfile cycleProfile(){return cycleProfile(1);}public static synchronized AnimationProfile cycleProfile(int direction){AnimationProfile[]v={AnimationProfile.OFF,AnimationProfile.SUBTLE,AnimationProfile.SMOOTH,AnimationProfile.EXPRESSIVE};int i=Arrays.asList(v).indexOf(profile);if(i<0)i=direction<0?0:v.length-1;AnimationProfile n=v[wrap(i+(direction<0?-1:1),v.length)];setProfile(n);return n;}public static synchronized void setProfile(AnimationProfile p){if(p==null||p==AnimationProfile.CUSTOM)return;profile=p;apply(p);saveProfile();}
 public static synchronized AnimationStyle cycleContainerStyle(int d){containerStyle=cycle(containerStyle,d);profile=matchingProfile();saveProfile();return containerStyle;}public static synchronized AnimationDirection cycleContainerDirection(int d){containerDirection=cycle(containerDirection,d);profile=matchingProfile();saveProfile();return containerDirection;}public static synchronized AnimationStyle cycleClosingStyle(int d){closingStyle=cycle(closingStyle,d);profile=matchingProfile();saveProfile();return closingStyle;}public static synchronized AnimationDirection cycleClosingDirection(int d){closingDirection=cycle(closingDirection,d);profile=matchingProfile();saveProfile();return closingDirection;}
