 public static synchronized DebugProfile debugProfile(){return debugProfile;}public static synchronized void setModernDebug(boolean enabled){modernDebug=enabled;saveDebug();}public static synchronized DebugProfile cycleDebugProfile(){DebugProfile[]v=DebugProfile.values();debugProfile=v[(debugProfile.ordinal()+1)%v.length];modernDebug=true;saveDebug();return debugProfile;}public static synchronized void cycleDebugMode(){if(!modernDebug){modernDebug=true;debugProfile=DebugProfile.COMPACT;}else if(debugProfile==DebugProfile.FULL)modernDebug=false;else cycleDebugProfile();saveDebug();}private static void saveDebug(){if(config!=null){config.get("debug","modernF3",false).set(modernDebug);config.get("debug","profile","STANDARD").set(debugProfile.name());config.save();}}
 public static synchronized void saveCatalogState(String q,String m,CatalogSort s,boolean only,int scroll){catalogSearch=q;catalogMod=m;catalogSort=s;catalogConfiguredOnly=only;catalogScroll=Math.max(0,scroll);config.get("catalog","search","").set(q);config.get("catalog","mod","all").set(m);config.get("catalog","sort","MOD_NAME").set(s.name());config.get("catalog","configuredOnly",false).set(only);config.get("catalog","scroll",0).set(catalogScroll);config.save();}
 private static void savePolicies(){if(config==null)return;List<String>o=new ArrayList<String>();for(Map.Entry<String,Policy>e:policies.entrySet())o.add(e.getKey()+"="+e.getValue());Collections.sort(o);config.get("compatibility","classPolicies",new String[0]).set(o.toArray(new String[o.size()]));config.save();}private static void saveRules(){if(config==null)return;List<String>o=new ArrayList<String>();for(Map.Entry<String,ScreenRule>e:rules.entrySet()){ScreenRule r=e.getValue();o.add(e.getKey()+"|"+r.duration+"|"+r.offset+"|"+r.easing+"|"+r.style+"|"+r.direction);}Collections.sort(o);config.get("compatibility","classAnimations",new String[0]).set(o.toArray(new String[o.size()]));config.save();}private static void saveClosingRules(){if(config==null)return;List<String>o=new ArrayList<String>();for(Map.Entry<String,ClosingRule>e:closingRules.entrySet()){ClosingRule r=e.getValue();o.add(e.getKey()+"|"+r.mode+"|"+r.duration+"|"+r.offset+"|"+r.easing+"|"+r.style+"|"+r.direction);}Collections.sort(o);config.get("compatibility","classClosingAnimations",new String[0]).set(o.toArray(new String[o.size()]));config.save();}
 private static void saveModPolicies(){saveEnumMap("modPolicies",modPolicies);}private static void saveModRules(){saveScreenRuleMap("modAnimations",modRules);}private static void saveModClosingRules(){saveClosingRuleMap("modClosingAnimations",modClosingRules);}
