 static Map.Entry<String,ScreenRule> parseScreenRule(String s){String[]p=s.split("\\|",6);if(p.length<4)return null;try{return new AbstractMap.SimpleImmutableEntry<String,ScreenRule>(p[0],new ScreenRule(clamp(Integer.parseInt(p[1]),0,600),clamp(Integer.parseInt(p[2]),0,48),ScreenEasing.valueOf(p[3]),p.length>=5?parseStyle(p[4]):AnimationStyle.SLIDE,p.length>=6?parseDirection(p[5]):AnimationDirection.UP));}catch(Exception ignored){return null;}}
