 static synchronized void resetForTests(){config=null;modernDebug=false;debugProfile=DebugProfile.STANDARD;policies.clear();rules.clear();closingRules.clear();backgroundModes.clear();modPolicies.clear();modRules.clear();modClosingRules.clear();modBackgroundModes.clear();}
 private static AnimationProfile parseProfile(String v){try{return AnimationProfile.valueOf(v);}catch(Exception e){return AnimationProfile.CUSTOM;}}private static ClosingMode parseMode(String v){try{return ClosingMode.valueOf(v);}catch(Exception e){return ClosingMode.SIMPLIFIED;}}private static AnimationStyle parseStyle(String v){try{return AnimationStyle.valueOf(v);}catch(Exception e){return AnimationStyle.SLIDE;}}private static AnimationDirection parseDirection(String v){try{return AnimationDirection.valueOf(v);}catch(Exception e){return AnimationDirection.UP;}}private static AnimationProfile matchingProfile(){for(AnimationProfile p:AnimationProfile.values())if(p!=AnimationProfile.CUSTOM&&matches(p))return p;return AnimationProfile.CUSTOM;}private static boolean matches(AnimationProfile p){return hotbar==p.h&&containers==p.c&&closing==p.x&&hotbarDuration==p.hd&&containerDuration==p.cd&&containerOffset==p.co&&closingDuration==p.xd&&closingOffset==p.xo&&containerStyle==AnimationStyle.SLIDE&&closingStyle==AnimationStyle.SLIDE&&containerDirection==AnimationDirection.UP&&closingDirection==AnimationDirection.UP;}private static void apply(AnimationProfile p){hotbar=p.h;containers=p.c;closing=p.x;if(!closing)closingMode=ClosingMode.DISABLED;else if(closingMode==ClosingMode.DISABLED)closingMode=ClosingMode.SIMPLIFIED;hotbarDuration=p.hd;containerDuration=p.cd;containerOffset=p.co;closingDuration=p.xd;closingOffset=p.xo;containerStyle=closingStyle=AnimationStyle.SLIDE;containerDirection=closingDirection=AnimationDirection.UP;}private static void saveProfile(){config.get("animations","profile","SMOOTH").set(profile.name());config.get("hotbar","enabled",true).set(hotbar);config.get("hotbar","durationMs",100).set(hotbarDuration);config.get("screens.containers","enabled",true).set(containers);config.get("screens.containers","durationMs",160).set(containerDuration);config.get("screens.containers","offsetPx",10).set(containerOffset);config.get("screens.containers","style","SLIDE").set(containerStyle.name());config.get("screens.containers","direction","UP").set(containerDirection.name());config.get("screens.closing","enabled",true).set(closing);config.get("screens.closing","durationMs",120).set(closingDuration);config.get("screens.closing","offsetPx",6).set(closingOffset);config.get("screens.closing","style","SLIDE").set(closingStyle.name());config.get("screens.closing","direction","UP").set(closingDirection.name());config.get("screens.closing","mode","SIMPLIFIED").set(closingMode.name());config.save();}private static int wrap(int v,int size){int r=v%size;return r<0?r+size:r;}private static int clamp(int v,int a,int b){return Math.max(a,Math.min(b,v));}
 private static AnimationStyle cycle(AnimationStyle v,int d){AnimationStyle[]a=AnimationStyle.values();return a[wrap(v.ordinal()+(d<0?-1:1),a.length)];}private static AnimationDirection cycle(AnimationDirection v,int d){AnimationDirection[]a=AnimationDirection.values();return a[wrap(v.ordinal()+(d<0?-1:1),a.length)];}
